/* @autogenerated */
package net.civeira.phylax.feature.oauth.theme.application;

import java.util.Locale;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.theme.domain.gateway.DecoratePageGateway;
import net.civeira.phylax.feature.template.page.application.PageDecorator;
import net.civeira.phylax.feature.template.page.domain.DecoratedPage;
import net.civeira.phylax.feature.template.page.domain.PageDecoration;

/**
 * Theme-aware implementation of {@link DecoratePageGateway}: a thin adapter over the
 * {@link PageDecorator} of the documents feature.
 *
 * <p>
 * The page template is {@code page.<template>} ({@code page.index} or {@code page.full}); the
 * {@code full} pages use the companion {@code <theme>-full} layout. When no theme layout is found
 * the built-in login shell with the static assets of {@code /oauth/themes/blue} is used.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class DecorateHtml implements DecoratePageGateway {

  static final String DEFAULT_THEME = "blue";

  private final PageDecorator decorator;

  @Override
  public String getFullPage(final String tenantName, final String title, final String innerContent,
      final Locale locale, final String template) {
    DecoratedPage page = decorator.decorate(PageDecoration.builder().tenant(tenantName).title(title)
        .innerContent(innerContent).locale(locale).pageTemplate("page." + template)
        .wide("full".equals(template)).defaultTheme(DEFAULT_THEME).build());
    return page.getHtml()
        .orElseGet(() -> builtInFallback(title, page.getBody(), page.getThemeName()));
  }

  private String builtInFallback(final String title, final String body, final String theme) {
    return "<html><head>" + "<meta charset=\"UTF-8\">\r\n"
        + "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n"
        + "<title>" + title + "</title>"
        + "<link rel=\"icon\" type=\"image/png\" href=\"/oauth/themes/" + theme + "/favicon.png\">"
        + "<link rel=\"stylesheet\" href=\"/oauth/themes/" + theme + "/styles.css\">\r\n"
        + "</head><body>"
        + "<div class=\"form-content\"><div class=\"loading\"></div><div class=\"in-form\">" + body
        + "</div></div>" + "</body></html>";
  }
}
